  customer: { id: customerId },
  orderDate: "2026-02-01",
  deliveryDate: "2026-02-01",
  orderLines: [{
    product: { id: productId },
    count: 1,
  }],
});
const orderId = orderRes?.value?.id;
console.log("Order ID:", orderId);

